 45	\section{Games and strategies}
 46	% Paper subsection label sec:strat kept for cross-reference fidelity.
 47	\label{sec:strat}
 48	
 49	\begin{definition}[Two-player one-round games]\label{def:game}
 50		A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
 51		\begin{enumerate}
 52			\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
 53			\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
 54			\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
 55			\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
 56		\end{enumerate}
 57	\end{definition}
 58	
 59	\begin{definition}[Tensor product strategies]\label{def:tensor-product-strategy}
 60		\uses{def:game, def:povm-conventions}
 61		A \emph{tensor product strategy} $\mathcal S$ for a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
 62		\begin{itemize}
 63			\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mathcal H_A \ot \mathcal H_B$ for finite-dimensional complex Hilbert spaces $\mathcal H_A$, $\mathcal H_B$,
 64			\item $A$ is a set $\{A^x\}$ such that for every $x \in \mathcal X$, $A^x = \{A^x_a\}_{a \in \mathcal A}$ is a POVM on $\mathcal H_A$, and
 65			\item $B$ is a set $\{B^y\}$ such that for every $y \in \mathcal Y$, $B^y = \{B^y_b\}_{b \in \mathcal B}$ is a POVM on $\mathcal H_B$.
 66		\end{itemize}
 67	\end{definition}
 68	
 69	\begin{definition}[Tensor product value]\label{def:tensor-product-value}
 70		\uses{def:tensor-product-strategy}
 71		The \emph{tensor product value} of a tensor product strategy $\mathcal S = (\ket{\psi}, A, B)$ with respect to a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is
 72		\[
 73			\operatorname{val}^*(\mathfrak G, \mathcal S) = \sum_{x,\,y,\,a,\,b} \mu(x,y)\, D(x,y,a,b)\, \bra{\psi} A^x_a \ot B^y_b \ket{\psi}\,.
 74		\]
 75		For $v \in [0,1]$ we say that the strategy $\mathcal S$ \emph{passes (or wins) $\mathfrak G$ with probability $v$} if $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge v$. The \emph{tensor product value} of $\mathfrak G$ is
 76		\[
 77			\operatorname{val}^*(\mathfrak G) = \sup_{\mathcal S} \operatorname{val}^*(\mathfrak G, \mathcal S)\,,
 78		\]
 79		where the supremum is taken over all tensor product strategies $\mathcal S$ for $\mathfrak G$.
 80	\end{definition}
 81	
 82	Unless specified otherwise, all strategies considered in what follows are tensor product strategies, and we simply call them \emph{strategies}; similarly, we refer to $\operatorname{val}^*(\mathfrak G)$ as the \emph{value} of the game $\mathfrak G$.
 83	
 84	% The source labels this definition def:projective-strategy. That label is already carried
 85	% by the low individual degree test track (Chapter 2), where it names the strategy format
 86	% specific to that test, so a distinct label is used here; see the following remark.
 87	\begin{definition}[Projective strategies]\label{def:projective-strategy-general}
 88		\uses{def:tensor-product-strategy, def:povm-conventions}
 89		A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{projective} if all the measurements $\{A^x_a\}_a$ and $\{B^y_b\}_b$ are projective.
 90	\end{definition}
 91	
 92	\begin{remark}[Two uses of the term ``projective strategy'']\label{rem:projective-strategy-relation}
 93		Definition~\ref{def:projective-strategy-general} is the general notion: a strategy for an arbitrary nonlocal game all of whose measurements are projective. The low individual degree chapters use the same term for the concrete data of a two-prover strategy for the $(m,q,d)$ low individual degree test (Definition~\ref{def:projective-strategy} in Chapter~\ref{chap:test}); that definition is the specialization of the present notion to the question format of that particular test. The two usages occur in disjoint contexts.
 94	\end{remark}
 95	
 96	\begin{definition}[Symmetric games and symmetric strategies]\label{def:symmetric-game}
 97		% Paper label: rem:symmetric-games (a definition environment carrying a rem: label in the
 98		% source); relabeled here to match the environment kind.
 99		\uses{def:game, def:tensor-product-strategy}
100		A game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is \emph{symmetric} if the question and answer alphabets are the same for both players (i.e.\ $\mathcal X = \mathcal Y$ and $\mathcal A = \mathcal B$), the distribution $\mu$ is symmetric (i.e.\ $\mu(x,y) = \mu(y,x)$ for all $x,y$), and the decision predicate $D$ treats both players symmetrically (i.e.\ $D(x,y,a,b) = D(y,x,b,a)$ for all $x,y,a,b$).
101	
102		A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{symmetric} if $\ket{\psi}$ is a (pure) state in $\mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, that is invariant under permutation of the two factors, and the measurement operators of both players are identical.
103	\end{definition}
104	
105	We often specify symmetric games $\mathfrak G$ and symmetric strategies $\mathcal S$ using a compact notation: we write $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ and $\mathcal S = (\ket{\psi}, M)$, where $M$ denotes the set of measurement operators shared by both players.
106	
107	% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:94-103) concludes with a
108	% strategy of value at least 1-eps; its proof yields only the approximate form stated here, and
109	% the supremum defining val* need not be attained. See rem:symmetric-strat-limit.
110	\begin{lemma}[Symmetrization of strategies for symmetric games]\label{lem:symmetric-strat}
111		\uses{def:symmetric-game, def:tensor-product-value, def:projective-strategy-general}
112		Let $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ be a symmetric game such that $\operatorname{val}^*(\mathfrak G) = 1-\eps$ for some $\eps \ge 0$. Then for every $\eps' > \eps$ there exists a symmetric and projective strategy $\mathcal S = (\ket{\psi}, M)$ such that $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge 1-\eps'$.
113	\end{lemma}
114	\begin{proof}
115		\uses{thm:naimark}
116		Fix $\eps' > \eps$. Since $\operatorname{val}^*(\mathfrak G)$ is the supremum of the values of all strategies, there exists a strategy $\mathcal S' = (\ket{\psi'}, A, B)$ with $\operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$. Using Naimark dilation (Theorem~\ref{thm:naimark}, in the completed form recorded in Remark~\ref{rem:naimark-for-games}) we may assume without loss of generality that $\ket{\psi'} \in \C^d_{A'} \ot \C^d_{B'}$ for some integer $d$ and that every $A^x$ and $B^x$ is a projective measurement. Let
117		\[
118			\ket{\psi} = \frac{1}{\sqrt 2}\, \bigl( \ket{0}_{A}\ket{1}_{B}\ket{\psi'}_{A'B'} + \ket{1}_{A}\ket{0}_{B}\ket{\psi'_\tau}_{A'B'} \bigr) \in \bigl(\C^2_{A} \ot \C^d_{A'}\bigr) \ot \bigl(\C^2_{B} \ot \C^d_{B'}\bigr)\,,
119		\]
120		where $\ket{\psi'_\tau}$ is obtained from $\ket{\psi'}$ by permuting the two players' registers; then $\ket{\psi}$ is invariant under permutation of the register pairs $AA'$ and $BB'$. For each question $x \in \mathcal X$ define the projective measurement $M^x = \{M^x_a\}_{a \in \mathcal A}$ on $\C^2 \ot \C^d$ by
121		\[
122			M^x_a = \ket{0}\bra{0} \ot A^x_a + \ket{1}\bra{1} \ot B^x_a\,,
123		\]
124		and let each player measure $M$ on their pair of registers. Because the decision predicate $D$ of the symmetric game treats the two players symmetrically, the resulting symmetric projective strategy $\mathcal S = (\ket{\psi}, M)$ satisfies $\operatorname{val}^*(\mathfrak G, \mathcal S) = \operatorname{val}^*(\mathfrak G, \mathcal S') \ge 1-\eps'$.
125	\end{proof}
126	
127	\begin{remark}[Attainment in the symmetrization lemma]\label{rem:symmetric-strat-limit}
128		The source states the conclusion of Lemma~\ref{lem:symmetric-strat} in the stronger form: there exists a symmetric projective strategy of value at least $1-\eps$. Its proof, reproduced above, produces, for each $\eps' > \eps$, such a strategy of value at least $1-\eps'$, and the stronger form does not follow: the dilated dimension $d$ may grow as $\eps' \downarrow \eps$, and the supremum defining $\operatorname{val}^*(\mathfrak G)$ in Definition~\ref{def:tensor-product-value} need not be attained by any strategy. The statement above therefore records the approximate conclusion, which is what the proof establishes; the stronger form would require an additional attainment or compactness argument.
129	\end{remark}
130	
131	\begin{definition}[Commuting strategies]\label{def:comm-strategy}
132		\uses{def:game, def:tensor-product-strategy}
133		Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a game, and let $\mathcal S = (\ket{\psi}, A, B)$ be a strategy for $\mathfrak G$ such that $\mathcal H_A = \mathcal H_B$. We say that $\mathcal S$ is a \emph{commuting strategy for $\mathfrak G$} if for all question pairs $(x,y)$ in the support of $\mu$ (i.e.\ all $(x,y)$ with $\mu(x,y) > 0$) we have
134		\[
135			[A^x_a, B^y_b] = 0 \qquad \text{for all } a \in \mathcal A,\ b \in \mathcal B\,,
136		\]
137		where $[A,B] = AB - BA$ denotes the commutator.
138	\end{definition}
139	
140	\begin{definition}[Consistent measurements]\label{def:consistent-measurement}
141		\uses{def:povm-conventions}
142		Let $\mathcal A$ be a finite set, let $\ket{\psi} \in \mathcal H \ot \mathcal H$ be a state, and let $\{M_a\}_{a \in \mathcal A}$ be a projective measurement on $\mathcal H$. We say that \emph{$\{M_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$} if and only if
143		\[
144			\forall a \in \mathcal A\,, \qquad M_a \ot \Id_B\, \ket{\psi} = \Id_A \ot M_a\, \ket{\psi}\,.
145		\]
146		When the state $\ket{\psi}$ is clear from context we simply say that $\{M_a\}_{a \in \mathcal A}$ is consistent.
147	\end{definition}
148	
149	The terminology arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is
150	\[
151		\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot (M_a)^2 \ket{\psi} = \sum_a \bra{\psi} \Id_A \ot M_a \ket{\psi} = 1\,,
152	\]
153	where the first equality is by the definition of consistency, the second uses that $\{M_a\}$ is projective, and the last uses $\sum_a M_a = \Id$.
154	
155	\begin{definition}[Consistent strategies]\label{def:consistent-strategy}
156		\uses{def:consistent-measurement, def:projective-strategy-general}
157		Let $\mathcal S = (\ket{\psi}, A, B)$ be a projective strategy with state $\ket{\psi} \in \mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, defined on question alphabets $\mathcal X$ and $\mathcal Y$ and answer alphabets $\mathcal A$ and $\mathcal B$, respectively. We say that $\mathcal S$ is \emph{consistent} if for all $x \in \mathcal X$ the measurement $\{A^x_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$, and for all $y \in \mathcal Y$ the measurement $\{B^y_b\}_{b \in \mathcal B}$ is consistent on $\ket{\psi}$.
158	\end{definition}
159	
160	We almost always restrict attention to symmetric strategies; in this case consistency implies that whenever both players are sent the same question, they provide the same answer.
161	
162	\begin{definition}[PCC and SPCC strategies]\label{def:spcc}
163		\uses{def:projective-strategy-general, def:consistent-strategy, def:comm-strategy, def:symmetric-game}
164		We say that a strategy $\mathcal S$ for a game $\mathfrak G$ is \emph{PCC} if it is projective, consistent, and commuting for $\mathfrak G$. Additionally, we say that a PCC strategy $\mathcal S$ is \emph{SPCC} if it is furthermore symmetric.
165	\end{definition}
166	
167	\section{Distance measures}
168	
169	\begin{definition}[Distance between states]\label{def:state-distance}
170		Let $\{\ket{\psi_n}\}_{n \in \N}$ and $\{\ket{\psi'_n}\}_{n \in \N}$ be two families of states in the same space $\mathcal H$. For a function $\delta \colon \N \to [0,1]$ we say that $\{\ket{\psi_n}\}$ and $\{\ket{\psi'_n}\}$ are \emph{$\delta$-close}, denoted $\ket{\psi} \approx_\delta \ket{\psi'}$, if
171		\[
172			\lVert \ket{\psi_n} - \ket{\psi'_n} \rVert^2 = O(\delta(n))\,.
173		\]
174		The dependence of the states and of $\delta$ on the indexing parameter $n$ is generally left implicit; we write, e.g., $\ket{\psi}$ for $\ket{\psi_n}$.
175	\end{definition}
  1	\section{Nonlocal Games and $\MIP^*$}
  2	\label{sec:games}
  3	
  4	We introduce definitions associated with nonlocal games and strategies that will
  5	be used throughout.
  6	
  7	\subsection{Games and strategies}
  8	\label{sec:strat}
  9	
 10	\begin{definition}[Two-player one-round games]
 11	  \label{def:game}
 12	  A \emph{two-player one-round game} $\game$ is specified by a tuple
 13	  $(\cal{X}, \cal{Y}, \cal{A}, \cal{B}, \mu, D)$ where
 14	  \begin{enumerate}
 15	  \item $\cal{X}$ and $\cal{Y}$ are finite sets (called the \emph{question
 16	      alphabets}),
 17	  \item $\cal{A}$ and $\cal{B}$ are finite sets (called the \emph{answer
 18	      alphabets}),
 19	  \item $\mu$ is a probability distribution over $\cal{X} \times \cal{Y}$
 20	    (called the \emph{question distribution}), and
 21	  \item $D: \cal{X} \times \cal{Y} \times \cal{A} \times \cal{B} \to \{0,1\}$ is
 22	    a function (called the \emph{decision predicate}).
 23	  \end{enumerate}
 24	\end{definition}
 25	
 26	\begin{definition}[Tensor product strategies]
 27	  \label{def:tensor-product-strategy}
 28	  A \emph{tensor product strategy} $\strategy$ for a game $\game = (\cal{X},
 29	  \cal{Y}, \cal{A}, \cal{B}, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
 30	  \begin{itemize}
 31		\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mH_A \otimes \mH_B$ for finite
 32	    dimensional complex Hilbert spaces $\mH_A, \mH_B$,
 33		\item $A$ is a set $\{A^x\}$ such that for every $x \in \cal{X}$, $A^x =
 34	    \{A^x_a \}_{a \in \cal{A}}$ is a POVM over $\mH_A$, and
 35		\item $B$ is a set $\{B^y\}$ such that for every $y \in \cal{Y}$, $B^y =
 36	    \{B^y_b \}_{b \in \cal{B}}$ is a POVM over $\mH_B$.
 37	\end{itemize}
 38	\end{definition}
 39	
 40	\begin{definition}[Tensor product value]
 41	  \label{def:tensor-product-value}
 42		The \emph{tensor product value} of a tensor product strategy $\strategy =
 43	  (\ket{\psi}, A, B)$  with respect to a game $\game=(\cal{X}, \cal{Y}, \cal{A},
 44	  \cal{B}, \mu, D)$ is defined as
 45	  \begin{equation*}
 46			\val^*(\game, \strategy) = \sum_{x,\, y,\, a,\, b} \, \mu(x,y)\, D(x,y,a,b)\,
 47	    \bra{\psi} A^x_a \otimes B^y_b\, \ket{\psi}\;.
 48	  \end{equation*}
 49		For $v\in[0,1]$ we say that the strategy $\strategy$ \emph{passes (or wins)
 50	    $\game$ with probability $v$ if} $\val^*(\game, \strategy) \geq v$.
 51	  The \emph{tensor product value} of $\game$ is defined as
 52	  \begin{equation*}
 53			\val^*(\game) = \sup_\strategy \val^*(\game, \strategy)\;,
 54	  \end{equation*}
 55		where the supremum is taken over all tensor product strategies $\strategy$ for
 56	  $\game$.
 57	\end{definition}
 58	
 59	
 60	\begin{remark}
 61	  Unless specified otherwise, all strategies considered in this paper are tensor
 62	  product strategies, and we simply call them \emph{strategies}.
 63	  Similarly, we refer to $\val^*(\game)$ as the \emph{value} of the game
 64	  $\game$.
 65	\end{remark}
 66	
 67	
 68	\begin{definition}[Projective strategies]
 69	  \label{def:projective-strategy}
 70	  We say that a strategy $\strategy = (\ket{\psi}, A, B)$ is \emph{projective} if
 71	  all the measurements $\{A^x_a\}_a$ and $\{B^y_b\}_b$ are projective.
 72	\end{definition}
 73	
 74	\begin{definition}\label{rem:symmetric-games}
 75		A game $\game = (\cal{X}, \cal{Y}, \cal{A}, \cal{B}, \mu, D)$ is
 76	  \emph{symmetric} if the question and answer alphabets are the same for both
 77	  players (i.e.\
 78	  $\cal{X} = \cal{Y}$ and $\cal{A} = \cal{B}$), the distribution $\mu$ is
 79	  symmetric (i.e.\
 80	  $\mu(x,y) = \mu(y,x)$), and the decision predicate $D$ treats both players
 81	  symmetrically (i.e.\ for all $x,y,a,b$, $D(x,y,a,b) = D(y,x,b,a)$).
 82	 
 83	We call a strategy $\strategy = (\ket{\psi}, A, B)$
 84	  \emph{symmetric} if $\ket{\psi}$ is a (pure) state in $\mH \otimes \mH$, for some
 85	  Hilbert space $\mH$, that is invariant under permutation of the two factors,
 86	  and the measurement operators of both players are identical.
 87	\end{definition}
 88	
 89	We often specify symmetric games $\game$ and symmetric strategies $\strategy$ using
 90	  a compact notation: we write $\game = (\cal{X}, \cal{A}, \mu, D)$ and
 91	  $\strategy = (\ket{\psi}, M)$ where $M$ denotes the set of measurement
 92	  operators for both players.
 93	
 94	\begin{lemma}\label{lem:symmetric-strat}
 95	  Let $\game = (\cal{X}, \cal{A},  \mu, D)$ be a symmetric game
 96	  such that $\val^*(\game) = 1-\eps$ for some $\eps\geq 0$.
 97	  Then there exists a symmetric and projective strategy
 98	  $\strategy=(\ket{\psi},M)$ such that $\val^*(\game,\strategy)\geq 1-\eps$.
 99	\end{lemma}
100	
101	\begin{proof}
102	  By definition for any $\eps'>\eps$ there exists a strategy $\strategy'= (\ket{\psi'},A,B)$ such
103	  that $\val^*(\game,\strategy')\geq 1-\eps'$.
104	Using Naimark's theorem (Theorem~\ref{thm:naimark}) we can assume
105	without loss of generality that $\ket{\psi'}\in\C_{\alice'}^d\otimes \C_{\bob'}^d$ for some integer $d$
106	  and that for every $x$, $A^x$ and $B^x$ are projective measurements.
107	Let
108	  \[
109	    \ket{\psi} = \frac{1}{\sqrt{2}} \big( \ket{0}_\alice \ket{1}_\bob
110	    \ket{\psi'}_{\alice'\bob'} + \ket{1}_\alice \ket{0}_\bob
111	    \ket{\psi'_\tau}_{\alice'\bob'}\big) \in (\C_{\alice}^2 \otimes
112	    \C_{\alice'}^d) \otimes (\C_\bob^2 \otimes \C_{\bob'}^d)\;,
113	  \]
114	  where $\ket{\psi'_\tau}$ is obtained from $\ket{\psi}$ by permuting the two
115	  players' registers.
116	  Observe that $\ket{\psi}$ is invariant under permutation of $\alice\alice'$
117	  and $\bob\bob'$.
118	
119	  For any question $x\in \cal{X}$ define the measurement $M^x = \{M^x_a\}_{a \in \cal{A}}$
120	  acting on the Hilbert space $\C^2 \otimes \C^d$ as follows:
121	  \[
122	  	M^x_a = \ketbra{0}{0} \otimes A^x_a + \ketbra{1}{1} \otimes B^x_a \;,
123	  \]
124		i.e.\ for $\ket{\varphi} \in \C^d$, $M^x_a(\ket{0}\ket{\varphi})=\ket{0}A^x_a\ket{\varphi}$ and $M^x_a(\ket{1}\ket{\varphi})=\ket{1}B^x_a\ket{\varphi}$.
125	  When Alice receives question $x$, she measures $M^x$ on registers $\alice \alice'$, and when Bob receives 
126	  question $y$, he measures $M^y$ on registers $\bob \bob'$.
127	Using that by assumption the decision predicate $D$ for $\game$ is symmetric,
128	  it is not hard to verify that $\val^*(\game,\strategy) =
129	  \val^*(\game,\strategy')$.
130	\end{proof}
131	
132	\begin{definition}
133	  \label{def:comm-strategy}
134	  Let $\game = (\cal{X}, \cal{Y}, \cal{A}, \cal{B}, \mu, D)$ be a game, and let
135	  $\strategy = (\ket{\psi}, A, B)$ be a strategy for $\game$ such that  $\mH_A = \mH_B$.
136	  Let $S \subseteq \cal{X} \times \cal{Y}$ denote the support of the question
137	  distribution $\mu$, i.e.\ the set of $(x,y)$ such that $\mu(x,y)>0$.
138	  We say that $\strategy$ is a \emph{commuting strategy for $\game$} if for all
139	  question pairs $(x, y) \in S$, we have $[A^x_a, B^y_b] = 0$ 
140	  for all $a
141	  \in \cal{A}, b \in \cal{B}$, where $[A, B] = AB - BA$ denotes the commutator.
142	\end{definition}
143	
144	\begin{definition}[Consistent measurements]
145	  \label{def:consistent-measurement}
146	  Let $\cal{A}$ be a finite set, let $\ket{\psi} \in \mH \otimes \mH$ be a
147	  state, and let $\{ M_a \}_{a \in \cal{A}}$ be a projective measurement on
148	  $\mH$.
149	  We say that \emph{$\{M_a\}_{a \in \cal{A}}$ is consistent on $\ket{\psi}$} if
150	  and only if
151	  \begin{equation*}
152	    \forall a \in \mA\;,\quad M_a \otimes \Id_\bob\, \ket{\psi}
153	    = \Id_\alice \otimes M_a\, \ket{\psi}\;.
154	  \end{equation*}
155		When the state $\ket{\psi}$ is clear from context we simply say that \emph{$\{M_a\}_{a \in \cal{A}}$ is consistent}.
156	\end{definition}
157	
158	The terminology ``consistent'' arises from the fact that when the measurement $\{M_a\}$ is performed on both registers of $\ket{\psi}$, the probability of obtaining twice the same outcome is 
159	\[ \sum_a \bra{\psi} M_a \otimes M_a \ket{\psi}\,=\, \sum_a \bra{\psi} \Id_\alice \otimes (M_a)^2 \ket{\psi} \,=\, \sum_a \bra{\psi} \Id_\alice \otimes M_a \ket{\psi} \,=\,1\;,\]
160	where the first equality is by definition of consistency, the second uses that $\{M_a\}$ is projective, and the last uses $\sum_a M_a=\Id$. 
161	
162	\begin{definition}[Consistent strategies]
163	  \label{def:consistent-strategy}
164		Let $\strategy = (\ket{\psi}, A, B)$ be a projective strategy with state
165	  $\ket{\psi} \in \mH \otimes \mH$, for some Hilbert space~$\mH$, which is
166	  defined on question alphabets $\cal{X}$ and~$\cal{Y}$ and answer alphabets
167	  $\cal{A}$ and~$\cal{B}$, respectively.
168	  We say that the strategy $\strategy$ is \emph{consistent} if for all $x \in
169	  \cal{X}$, the measurement $\{A^x_a\}_{a \in \cal{A}}$ is consistent on
170	  $\ket{\psi}$ and if for all $y \in \cal{Y}$, the measurement $\{B^y_b\}_{b \in
171	    \cal{B}}$ is consistent on $\ket{\psi}$.
172	\end{definition}
173	
174	We almost always restrict our attention to symmetric strategies. In this case, consistency implies that whenever both players are sent the same question, they provide the same answer. 
175	
176	\begin{definition}
177	  \label{def:spcc}
178	  We say that a strategy $\strategy$ for a game $\game$ is \emph{PCC} if it is projective, consistent, and commuting for $\game$.
179	  Additionally, we say that a PCC strategy $\strategy$ is \emph{SPCC} if it is furthermore symmetric.
180	\end{definition}

  1	\chapter{The Pauli basis test}
  2	\label{chap:qpbt-test}
  3	% Paper label sec:pauli-verifier kept for cross-reference fidelity; it resolves to this chapter.
  4	\label{sec:pauli-verifier}
  5	
  6	This chapter defines the two testing primitives underlying the question-reduction step: the \emph{classical low individual degree game}, in its simultaneous form, and the \emph{Pauli basis test}, a nonlocal game built from the classical game together with the Magic Square game. We state the quantum soundness of the classical game (Theorem~\ref{lem:ld-soundness}, imported; see Remark~\ref{rem:ld-soundness-provider}), the rigidity of the Magic Square game (Theorem~\ref{thm:ms-rigidity}, imported), completeness of the Pauli basis test (Lemma~\ref{lem:pauli-completeness}), and the main soundness theorem for the Pauli basis test (Theorem~\ref{thm:pauli}), whose proof occupies Chapters~\ref{chap:qpbt-observables}--\ref{chap:qpbt-extraction} and is completed in Chapter~\ref{chap:qpbt-extraction}. The chapter closes with the qubit form of the soundness statement (Corollary~\ref{cor:pauli-binary}) and the canonical parameter choice with its soundness bound (Definition~\ref{def:introparams}, Lemma~\ref{lem:delta-bound}).
  7	
  8	Throughout, the two players are denoted $\mathrm A$ and $\mathrm B$; for $w \in \{\mathrm A,\mathrm B\}$ we write $\overline w$ for the other player. Games, strategies, values, conditionally linear (CL) functions and distributions, typed distributions sampled from the edges of a graph, and the state-dependent approximation $\approx_\delta$ between families of measurement operators are as in Chapter~\ref{chap:qpbt-games}; the algebraic material on lines, canonical linear maps, the low-degree encoding, and generalized Pauli observables is from Chapter~\ref{chap:qpbt-algebra}.
  9	
 10	\section{The classical low individual degree game}
 11	% Paper labels sec:ld-verifier and sec:ld-game kept for cross-reference fidelity.
 12	\label{sec:ld-verifier}
 13	\label{sec:ld-game}
 14	
 15	The classical low individual degree game is a two-player game based on the low individual degree variant of the multilinearity test of Babai, Fortnow, and Lund. In the basic version, one player (the ``points player'') receives a uniformly random point $u \in \F_q^m$ and answers with a value $a \in \F_q$, while the other player (the ``lines player'') receives a random line through $u$ --- either axis-parallel or diagonal --- and answers with a univariate polynomial describing the restriction of a global function to that line. If the players share a polynomial $g\colon \F_q^m \to \F_q$ of individual degree at most $d$ and answer with $g(u)$ and with the restriction $g|_\ell$, they win with probability $1$; the soundness theorem below states that the converse approximately holds. In the simultaneous version, the players' answers are $k$-tuples, checked coordinatewise against a $k$-tuple of low individual degree polynomials.
 16	
 17	\begin{definition}[The classical low individual degree game: parameters and registers]\label{def:ld-game}
 18		\uses{def:game, def:admissible-size}
 19		The game $\mathcal G^{\mathrm{ld}}$ is parametrized by a tuple $\mathsf{ldparams} = (q,m,d,k)$, where $m,d,k \in \N$, $q \in \N$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. We write $\mathcal G^{\mathrm{ld}}_{\mathsf{ldparams}}$ to emphasize the dependence on the parameter tuple. The type set of $\mathcal G^{\mathrm{ld}}$ is
 20		\[
 21			\mathcal T^{\mathrm{ld}} = \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}\}\;,
 22		\]
 23		and the distribution over type pairs $(t_{\mathrm A}, t_{\mathrm B})$ is uniform over $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$. The ambient space is the direct sum $V = V_X \oplus V_I \oplus V_V$ of three register subspaces: the \emph{point register} $V_X \cong \F_q^m$, the \emph{coordinate register} $V_I \cong \F_q$, and the \emph{direction register} $V_V \cong \F_q^m$. Elements of $V$ are identified with triples $(u,s,v) \in \F_q^m \times \F_q \times \F_q^m$. The question distribution and the win predicate of $\mathcal G^{\mathrm{ld}}$ are specified in Definitions~\ref{def:ld-question-distribution} and~\ref{def:ld-win-predicate} below.
 24	\end{definition}
 25	
 26	\begin{definition}[Question distribution of the classical low individual degree game]\label{def:ld-question-distribution}
 27		\uses{def:ld-game, def:cl-func, def:cl-dist, lem:cl-concat, def:cl-canonical, def:line-representative}
 28		Let $\mathsf{ldparams} = (q,m,d,k)$ be as in Definition~\ref{def:ld-game}. Define $L_{\mathsf{Point}}$ to be the $1$-level CL function on $V$ that projects onto $V_X$: for every $(u,s,v) \in V$,
 29		\begin{equation}
 30			\label{eq:cl-ptf}
 31			L_{\mathsf{Point}}(u,s,v) = (u,0,0)\;.
 32		\end{equation}
 33		For $s \in \F_q$, let $\chi(s)$ be the unique integer such that
 34		\begin{equation}
 35			\label{eq:chi-func}
 36			s = (\chi(s)-1)\,\frac{q}{m} + r
 37		\end{equation}
 38		for some $0 \le r < q/m$, where $s$ is interpreted as an integer in $\{0,1,\ldots,q-1\}$ under the identification of $\F_q$ with binary strings fixed in Chapter~\ref{chap:qpbt-algebra}. Since $m$ divides $q$, when $s$ is uniformly distributed on $\F_q$ the index $\chi(s)$ is uniformly distributed on $\{1,2,\ldots,m\}$. Define $L_{\mathsf{ALine}}$ by
 39		\begin{equation}
 40			\label{eq:cl-alnf}
 41			L_{\mathsf{ALine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{e_i}(u),\, s,\, 0\bigr)\quad\text{for all } (u,s,v) \in V\;,
 42		\end{equation}
 43		where $i = \chi(s)$ and $L^{\mathrm{Ln}}_v$ denotes the canonical linear map with one-dimensional kernel spanned by $v$, used to compute canonical representatives of lines (Definition~\ref{def:line-representative}). The function $L_{\mathsf{ALine}}$ is the concatenation (in the sense of Lemma~\ref{lem:cl-concat}) of the $1$-level CL function projecting $V_I \oplus V_V$ onto $V_I$ with the family of $1$-level CL functions $\{L^{\mathrm{Ln}}_{e_i}\}$ on $V_X$ indexed by $i \in \{1,\ldots,m\}$; thus $L_{\mathsf{ALine}}$ is a $2$-level CL function. Define $L_{\mathsf{DLine}}$ by
 44		\begin{equation}
 45			\label{eq:cl-dlnf}
 46			L_{\mathsf{DLine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u),\, s,\, \pi_{i-1}(v)\bigr)\;,
 47		\end{equation}
 48		where $i = \chi(s)$ and $\pi_{i-1}$ zeroes out the first $i-1$ coordinates of its input. The function $L_{\mathsf{DLine}}$ is the concatenation of (i) the identity on $V_I$, (ii) for each $i$ the $1$-level CL function $v \mapsto \pi_{i-1}(v)$ on $V_V$, and (iii) for each pair $(s,v') \in V_I \oplus V_V$ the $1$-level CL function $L^{\mathrm{Ln}}_{v'}$ on $V_X$; thus $L_{\mathsf{DLine}}$ is a $3$-level CL function.
 49	
 50		The question distribution of $\mathcal G^{\mathrm{ld}}$ is the typed CL distribution obtained as follows: sample a type pair $(t_{\mathrm A}, t_{\mathrm B})$ uniformly from $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$, sample $z = (u,s,v)$ uniformly from $V$, and send each player $w \in \{\mathrm A,\mathrm B\}$ the question $(t_w, L_{t_w}(z))$.
 51	\end{definition}
 52	
 53	The next two lemmas show that the CL functions $L_{\mathsf{Point}}$, $L_{\mathsf{ALine}}$, $L_{\mathsf{DLine}}$ give rise to the axis-parallel and diagonal line-versus-point distributions.
 54	
 55	\begin{lemma}\label{lem:alnf}
 56		\uses{def:ld-question-distribution, def:line}
 57		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,0),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, e_i)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a line that goes through $u$ and is parallel to a uniformly random axis $i \in \{1,2,\ldots,m\}$.
 58	\end{lemma}
 59	\begin{proof}
 60		\uses{def:line-representative}
 61		Since $s$ is uniformly random in $\F_q$ and $m$ divides $q$, the index $i = \chi(s)$ is uniformly random in $\{1,2,\ldots,m\}$, so $(u_0,s)$ specifies a uniformly random axis-parallel line $\ell(u_0,e_i)$. Since $u_0 = L^{\mathrm{Ln}}_{e_i}(u)$ is the canonical representative of the line through $u$ in direction $e_i$, we have $u \in \ell(u_0,e_i)$.
 62	\end{proof}
 63	
 64	\begin{lemma}\label{lem:dlnf}
 65		\uses{def:ld-question-distribution, def:line}
 66		Consider the pair $(\ell, u)$ sampled in the following way: first, sample the tuple $\bigl((u_0,s,v),(u,0,0)\bigr)$ from the CL distribution $\mu_{L_{\mathsf{DLine}}, L_{\mathsf{Point}}}$, and let $\ell = \ell(u_0, v)$ where $i = \chi(s)$. Then $u$ is a uniformly random point in $\F_q^m$, and $\ell$ is a random diagonal line that goes through $u$ and shares its first $i-1$ coordinates with $u$, for uniformly random $i \in \{1,2,\ldots,m\}$.
 67	\end{lemma}
 68	\begin{proof}
 69		\uses{lem:alnf}
 70		The proof is identical to that of Lemma~\ref{lem:alnf}: uniformity of $s$ makes $i = \chi(s)$ uniform, the direction component of the sampled tuple is $\pi_{i-1}(v)$ for uniform $v$ (so its first $i-1$ coordinates vanish), and $u_0 = L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u)$ places $u$ on the line $\ell(u_0,\pi_{i-1}(v))$.
 71	\end{proof}
 72	
 73	\begin{definition}[Line-point distributions]\label{def:line-point-dist}
 74		\uses{def:ld-question-distribution, lem:alnf, lem:dlnf}
 75		The \emph{axis line-point distribution} $D_{\mathsf{ALine}}$ is the distribution $\mu_{L_{\mathsf{ALine}}, L_{\mathsf{Point}}}$ over pairs $(\ell = (u_0,e_i),\, u)$, where we omit the $0$ components for simplicity. The \emph{diagonal line-point distribution} $D_{\mathsf{DLine}}$ is the distribution $\mu_{L_{\mathsf{DLine}}, L_{\mathsf{Point}}}$ over pairs $(\ell = (u_0,s,v),\, u)$. The \emph{line-point distribution} $D_{\mathsf{Line}}$ is the equal mixture of the two: with probability $\tfrac12$ output a sample from $D_{\mathsf{ALine}}$, and with probability $\tfrac12$ output a sample from $D_{\mathsf{DLine}}$.
 76	\end{definition}
 77	
 78	\begin{definition}[Win predicate of the classical low individual degree game]\label{def:ld-win-predicate}
 79		\uses{def:ld-game, def:ld-question-distribution, def:line, def:polyfunc}
 80		Fix $\mathsf{ldparams} = (q,m,d,k)$. Answers in the game $\mathcal G^{\mathrm{ld}}_{\mathsf{ldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
 81		\begin{itemize}
 82			\item Type $\mathsf{Point}$, question content $u \in \F_q^m$: the answer is an element of $\F_q^k$.
 83			\item Type $\mathsf{ALine}$, question content $(u_0,s) \in \F_q^m \times \F_q$, specifying the axis-parallel line $\ell(u_0,e_i)$ with $i = \chi(s)$: the answer is a $k$-tuple $(f_1,\ldots,f_k)$ of univariate polynomials $f_j\colon \F_q \to \F_q$ of degree at most $d$, each given by its $d+1$ coefficients.
 84			\item Type $\mathsf{DLine}$, question content $(u_0,s,v) \in \F_q^m \times \F_q \times \F_q^m$, specifying the diagonal line $\ell(u_0,v')$ with $v' = \pi_{i-1}(v)$ and $i = \chi(s)$: the answer is a $k$-tuple of univariate polynomials of degree at most $md$.
 85		\end{itemize}
 86		The win predicate $D^{\mathrm{ld}} = D^{\mathrm{ld}}_{\mathsf{ldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A,\mathrm B\}$; in all cases where no action is indicated, the predicate accepts.
 87		\begin{enumerate}
 88			\item (\textbf{Consistency test}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
 89			% The source phrases both clauses with "the" t such that x = u_0 + tv; that phrase
 90			% does not determine t on diagonal questions with direction v' = 0, which the
 91			% question distribution samples with positive probability. The universal
 92			% quantification over t used here is the local correction; see the remark below.
 93			\item (\textbf{Axis-parallel line-versus-point test}) If $t_w = \mathsf{ALine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t e_i$, where $i = \chi(s)$.
 94			\item (\textbf{Diagonal line-versus-point test}) If $t_w = \mathsf{DLine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t v'$, where $v' = \pi_{i-1}(v)$ and $i = \chi(s)$.
 95		\end{enumerate}
 96		The game $\mathcal G^{\mathrm{ld}}_{\mathsf{ldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{ld}}$, the question distribution of Definition~\ref{def:ld-question-distribution}, and win predicate $D^{\mathrm{ld}}_{\mathsf{ldparams}}$.
 97	\end{definition}
 98	
 99	\begin{remark}[Diagonal questions with zero direction]\label{rem:ld-win-zero-direction}
100		The source states the two line-versus-point clauses with ``the'' $t \in \F_q$ such that $x_{\overline w} = u_0 + t v$. When the direction is nonzero and $x_{\overline w}$ lies on the line, exactly one such $t$ exists and the formulation above agrees with the source. But zero directions occur: Definition~\ref{def:line} explicitly permits them, and the question distribution of Definition~\ref{def:ld-question-distribution} produces $\mathsf{DLine}$ questions with $v' = \pi_{i-1}(v) = 0$ with positive probability, namely whenever the last $m - i + 1$ coordinates of $v$ vanish. In that case $\ell(u_0, 0) = \{u_0\}$, every $t \in \F_q$ satisfies $x_{\overline w} = u_0 + t v'$ when $x_{\overline w} = u_0$, and the source clause does not determine acceptance for a nonconstant answer polynomial. The universal quantification over $t$ adopted in Definition~\ref{def:ld-win-predicate} makes the predicate a well-defined function of its arguments; it accepts vacuously when no such $t$ exists, a case the question distribution never produces. Completeness is unaffected: the restriction of a polynomial $g$ to the singleton line $\ell(u_0,0)$, expressed through the parameterization $t \mapsto u_0 + t \cdot 0$, is the constant polynomial with value $g(u_0)$, which passes the check for every $t$.
101	\end{remark}
102	
103	The soundness properties of the low individual degree game are expressed in terms of the following class of measurements.
104	
105	\begin{definition}[Low-degree polynomial measurements]\label{def:ld-meas}
106		\uses{def:polyfunc, def:polymeasurements, def:polynomials-degree}
107		Let $\polymeas{m}{q}{d}$ denote the set of POVM measurements indexed by $\polyfunc{m}{q}{d}$, the polynomial representatives of individual degree at most $d$ in each variable; this is the notion of Definition~\ref{def:polymeasurements}, and the argument order $(m,q,d)$ follows that definition (the paper orders the arguments as $(m,d,q)$). By Definition~\ref{def:polynomials-degree}, evaluation identifies these representatives with the corresponding polynomial functions $g\colon \F_q^m \to \F_q$, bijectively whenever $d \le q-1$; the parameter regimes of this chapter (Definition~\ref{def:introparams} fixes $d = 1$, and admissibility gives $q \ge 2$) always satisfy this. More generally, for an integer $k$ and tuples $m = (m_1,\ldots,m_k)$, $q = (q_1,\ldots,q_k)$, $d = (d_1,\ldots,d_k)$, let $\mathrm{PolyMeas}(m,q,d,k)$ denote the set of measurements $G = \{G_{g_1,\ldots,g_k}\}$ such that for each $i \in \{1,\ldots,k\}$, the outcome index $g_i$ is a polynomial $g_i\colon \F_{q_i}^{m_i} \to \F_{q_i}$ of individual degree at most $d_i$.
108	\end{definition}
109	
110	Quantum soundness of a version of the classical low-degree test for polynomials of low \emph{total} degree was claimed by Natarajan and Vidick, building on an analysis of a three-prover version of the test by Vidick; there is a known gap in the soundness analysis of that test, and it is not used here. Instead, the construction relies on the low \emph{individual} degree test, whose quantum soundness is proved in~\cite{Ji2020LowIndividualDegree} and generalized in~\cite{Ji2021Quantum}. The statement below is the form most directly useful in what follows.
  1	\section{Classical and Quantum Low-degree Tests}
  2	\label{sec:ldt}
  3	
  4	In this section we introduce the classical and quantum low individual degree tests, that form the basis of our classical, quantum-sound and quantum PCP constructions. For quantum soundness of the classical test we refer to~\cite{ML20}. For the quantum test, we refer to~\cite{natarajan2018low} and its adaptation to the low individual degree test given in Appendix~\ref{sec:qld-analysis}. 
  5	The protocol in this work combines both of these tests, using the quantum
  6	low individual degree test for question reduction and the classical low individual degree test for
  7	answer reduction.
  8	Section~\ref{sec:ld-verifier} below introduces the classical test,
  9	and Section~\ref{sec:pauli-verifier} does the same for the quantum 
 10	test.
 11	Prior to doing this, we introduce the \emph{Magic Square game} in
 12	Section~\ref{sec:ms}, a key subroutine in the quantum test.
 13	
 14	
 15	\subsection{The classical low-degree test}
 16	\label{sec:ld-verifier}
 17	
 18	We begin with a generalization of the classical low-degree test known as the
 19	``simultaneous individual low-degree test''.
 20	We sometimes refer to this as the ``classical low-degree test'' for short.
 21	The low-degree test is used as a subroutine in the Pauli Basis test (see
 22	Section~\ref{sec:pauli-verifier}) as well as the answer-reduction normal form
 23	verifier (see Section~\ref{sec:ans}).
 24	We describe the test as a nonlocal game in Section~\ref{sec:ld-game} and show
 25	that the question distribution can be implemented as a (typed) conditionally
 26	linear distribution (see \Cref{sec:types} for the definition of typed CL
 27	distributions).
 28	
 29	
 30	\subsubsection{The game}
 31	\label{sec:ld-game}
 32	
 33	The game $\game^\ld$ is parametrized by a tuple $\ldparams = (q, m, d, \ldc)$
 34	where $m, d, \ldc \in \N$ are integers, $q \in \N$ is an admissible field size,
 35	and $m$ divides $q$.
 36	We sometimes write $\game^\ld_\ldparams$ to emphasize the dependence of the
 37	classical low-degree test on the parameter tuple $\ldparams$.
 38	
 39	We first provide a high-level description of the game for $k=1$.
 40	It is based on the low-individual degree variant of the multilinearity test
 41	of~\cite{babai1991non}, where one player (called the ``points player'') receives
 42	a random point $u \in \F_q^m$, and the other player (called the ``lines
 43	player'') receives a random axis-parallel line $\line$ that contains $u$, i.e.\
 44	the line parallel to the $i$-th axis which goes through point $u$, for uniformly
 45	random $i\in\{1,\ldots,m\}$.
 46	The points player is supposed to respond with a value $a \in \F_q$, and the
 47	lines player is supposed to respond with a univariate polynomial $f_\line$ of
 48	degree at most $d$ such that $f_\line(u_i) = a$, where $u_i$ is the $i$-th
 49	coordinate of $u$.
 50	
 51	Suppose the players agree beforehand on a global polynomial $g: \F_q^m \to \F_q$
 52	such that every variable has degree at most $d$.
 53	Then a winning strategy is the following: the points player responds with
 54	$g(u)$, and the lines player responds with the univariate polynomial $f_\line$
 55	that is the restriction of $g$ to line $\line$; formally, for $t \in \F_q$,
 56	\[f_\line(t)=g(u_1,u_2,\ldots,u_{i-1},t,u_{i+1},\ldots,u_m)\;.\] It is easy to
 57	see that $f_\line(t)$ has degree at most $d$ in the variable $t$.
 58	Thus in this case the players will pass the low-degree test with probability
 59	$1$.
 60	The low-degree testing theorem states that the converse approximately holds: if
 61	the players pass the low-degree test with probability close to $1$, then their
 62	responses must be approximately consistent (in some sense) with a global
 63	polynomial $g$ with individual degree $d$.
 64	
 65	When $k > 1$, the players are supposed to respond with a \emph{tuple} of
 66	answers; and the test is intended to check that the players' responses are
 67	consistent with a $k$-tuple of functions $g_i: \F_q^m \to \F_q$ that are
 68	polynomials where every variable has degree at most $d$.
 69	
 70	The game that we use is slightly more elaborate than the ``axis-parallel
 71	lines-versus-points'' test just described.
 72	In addition, we have two other subtests.
 73	One is a ``diagonal line-vs-points'' test: here, the points player receives a
 74	point $u \in \F_q^m$ as before, but the lines player receives a line $\line$
 75	that goes through $u$ but is not necessarily axis-aligned.
 76	Instead, it's chosen by first picking an index $i \in \{1,2,\ldots,m\}$
 77	uniformly at random, picking $v \in \F_q^m$ uniformly at random, and letting $v'
 78	= \pi_{i-1}(v) = (0,0,\ldots,0,v_i,v_{i+1},\ldots,v_m)$ (i.e., $\pi_{i-1}$
 79	zeroes out the first $i-1$ coordinates of its input).
 80	Then, the line is defined as the set
 81	\[
 82		\line = \{ u + tv' : t \in \F_q \}\;,
 83	\]
 84	which is a uniformly random line in the affine subspace of $\F^m_q$
 85	corresponding to all points $v$ whose first $(i-1)$ coordinates match those of
 86	$u$.
 87	The points player responds with a value $a \in \F_q$, the lines player responds
 88	with a univariate polynomial $f_\line$ of degree $md$,\footnote{Since $\line$ is
 89	  no longer axis-parallel, the restriction of an individual degree-$d$
 90	  polynomial $g$ to a line $\line$ may yield a degree $md$ polynomial.}
 91	and the verifier checks that $f_\line(t_u) = a$ (where $t_u \in \F_q$ is the
 92	projection of $u$ onto the line $\line$ with respect to a canonical
 93	parameterization of $\line$).
 94	
 95	The other additional test is a ``consistency test'', where both players receive
 96	either the same points question, the same axis-parallel lines question, or the
 97	same diagonal lines question.
 98	In all cases they are expected to respond with the same answer.
 99	
100	
101	
102	\paragraph{Axis-parallel lines and diagonal lines.}
103	Before presenting a formal description of the game $\game^\ld$, we first define
104	what we mean by lines, and their properties.
105	
106	\begin{definition}[Lines]
107	  \label{def:line}
108		A \emph{line} $\line$ in $\F^m_q$ specified by a pair $(u,v) \in (\F_q^m)^2$
109	  is the subset
110	  \begin{equation}
111	    \label{eq:line-set}
112	    \line(u,v) = \bigl\{\, u + tv : t \in \F_q \,\bigr\} \subseteq \F_q^m \;.
113	  \end{equation}
114	  We call the vector $v$ a \emph{direction} of line
115	  $\line(u,v)$.\footnote{For convenience we explicitly allow
116	    $v=0$, in which case the line is reduced to a singleton.}
117	  
118	  A line $\line(u,v)$ is \emph{axis-parallel} if there is a coordinate $i \in
119	  \{1,2,\ldots,m\}$ for which $v$ is equal to $e_i$, the $i$-th elementary basis
120	  vector in $\F_q^m$.
121	  We say that such a line $\line$ is \emph{parallel to the $i$-th direction}.
122	  A line $\line(u,v)$ is \emph{diagonal} if there exists an $i \in
123	  \{0,1,\ldots,m-1\}$ for which $v_1 = v_2 = \cdots = v_i = 0$.
124	\end{definition}
125	
126	The following Proposition establishes that, for a fixed direction, a line
127	$\line$ is an equivalence class of points on the line.
128	\begin{proposition}
129	  \label{prop:line-equiv}
130	  Let $u,v \in \F_q^m$.
131	  Then for all $u' \in \line(u,v)$, we have that $\line(u,v) = \line(u',v)$.
132	\end{proposition}
133	\begin{proof}
134		Fix $u' \in \line(u,v)$.
135	  We have that $u' = u + tv$ for some $t \in \F_q$.
136	  Let $a \in \line(u,v)$.
137	  This means that $a = u + sv$ for some $s\in \F_q$.
138	  We also have that $a = u + (s - t + t)v = u + tv + (s - t)v = u' + (s - t)v$,
139	  so $\line(u,v) \subseteq \line(u',v)$.
140	  A similar argument shows that $\line(u',v) \subseteq \line(u,v)$.
141	\end{proof}
142	
143	We now specify a canonical representation of lines $\line = \line(u,v)$ as pairs $(u_0,v)$
144	where $u_0$ is a \emph{canonical representative} of $\line$ specified as
145	follows.
146	Let $L_v^{\lnf}: \F_q^m \to \F_q^m$ denote the canonical linear map with the
147	one-dimensional kernel basis $\{v\}$ (see \Cref{def:cl-canonical} for a
148	definition of canonical linear map).
149	Note that for all $u \in \line$, we have that $L_v^{\lnf}(u)$ is a point in
150	$\line$.
151	This is because since the image and kernel of $L_v^{\lnf}$ are complementary
152	subspaces by definition (see \Cref{def:cl-canonical}), any $u \in \F_q^m$ has a
153	unique decomposition $u = u_0 + u_1$ where $u_0$ is in the image of $L_v^{\lnf}$
154	and $u_1 \in \ker(L_v^{\lnf})$, which by definition is the subspace spanned by
155	$v$.
156	Thus $u_1 = tv$ for some $t \in \F_q$ and we have that $u_0 = u - tv \in \line$.
157	In particular, if $u\in \line$ then $u_0 = L_v^{\lnf}(u) \in \line$ as well. 
158	Furthermore, since $L_v^{\lnf}$ is a projection onto its image by definition, we
159	have $L_v^{\lnf}(u_0) = u_0$.
160	
161	Next, note that for any $u,u' \in \line$, since $u-u' = sv$ for some $s\in \F_q$
162	it follows that $L_v^\lnf(u) = L_v^\lnf(u')$.
163	Thus $u_0 = u_0'$ and this shows that $L_v^\lnf$ gives a means to compute a
164	canonical representative of lines.
165	
166	\begin{definition}[Canonical representative of a line]
167	  \label{def:line-representative}
168	  Let $\line$ be a line in direction $v$.
169	  A canonical representative of $\line$ is the point $u_0 \in \F_q^m$ such that
170	  \[
171	    u_0 = L_v^\lnf(u)
172	  \]
173	  for all $u \in \line$.
174	\end{definition}
175	
176	
177	
178	\paragraph{Question distribution.}
179	We now present the question distribution of the game $\game^\ld$ as a typed CL
180	distribution (see \Cref{sec:types} for the definition of typed CL functions and
180	distribution (see \Cref{sec:types} for the definition of typed CL functions and
181	typed CL distributions).
182	The type set $\type^\ld$ of the game $\game^\ld$ we use is
183	\[
184		\type^\ld = \{ \Point, \ALine, \DLine \}\;.
185	\]
186	The distribution over question types is uniform over $\type^\ld \times \type^\ld$. 
187	
188	We introduce the corresponding typed CL functions $L_\Point$, $L_\ALine$,
189	$L_\DLine$ where the corresponding CL distributions $\mu_{L_\ALine,L_\Point}$
190	and $\mu_{L_\DLine,L_\Point}$ implement the axis line-versus-point and diagonal
191	line-versus-point distributions, respectively.
192	The functions are parametrized by a field size $q$, a dimension $m$, and three
193	complementary register subspaces $V_\xpt,V_{\coord}, V_{\dir{}}$ of some ambient
194	space.
195	The register $V_\xpt$ (which is isomorphic to $\F_q^m$) is called the
196	\emph{point register}, $V_\coord$ (which is isomorphic to $\F_q$) is called the
197	\emph{coordinate register}, and $V_{\dir{}}$ (which is isomorphic to $\F_q^m$)
198	is called the \emph{direction register}, respectively.
199	We let $V$ denote the direct sum $V_\xpt \oplus V_{\coord} \oplus V_{\dir{}}$.
200	We identify elements of $V$ as triples $(u,s,v) \in \F_q^m \times \F_q \times
201	\F_q^m$.
202	
203	Define $L_\Point$ to be the $1$-level CL function that projects onto $V_\xpt$: for every $(u,s,v) \in V$,
204	\begin{equation}
205	  \label{eq:cl-ptf}
206		L_\Point(u,s,v) = (u,0,0) \;.
207	\end{equation}
208	Define $L_\ALine$ to be the following $2$-level CL function:
209	\begin{equation}
210	  \label{eq:cl-alnf}
211		L_\ALine(u,s,v) = (L^\lnf_{e_i}(u), s, 0)\ \text{for all } (u,s,v) \in V,
212	\end{equation}
213	where $L^\lnf$ is the linear function used to compute the canonical
214	representative of lines (see \Cref{def:line-representative}), and $i = \chi(s)$
215	where we define $\chi(s)$ to be the unique integer such that
216	\begin{equation}
217	\label{eq:chi-func}
218		s = (\chi(s) - 1) \frac{q}{m} + r
219	\end{equation}
220	for some $0 \leq r < q/m$, and we interpret the field element $s \in \F_q$ as an
221	integer between $0$ and $q - 1$).
222	The function $L_\ALine$ is the concatenation of the $1$-level CL function that
223	projects the subspaces $V_{\coord} \oplus V_{\dir{}}$ down to $V_\coord$ (i.e.
224	zeroes out the entire $V_{\dir{}}$ register), and the family of $1$-level CL
225	functions $\{L^\lnf_{e_i} \}$ acting on $V_\xpt$, indexed by $i \in
226	\{1,2,\ldots,m\}$.
227	(See \Cref{lem:cl-concat} for definition of CL function concatenation.)
228	Thus $L_\ALine$ is a $2$-level CL function.
229	
230	Define $L_\DLine$ to be the following $3$-level CL function: for all $(u,s,v) \in
231	V$,
232	\begin{equation}
233	\label{eq:cl-dlnf}
234		L_\DLine(u,s,v) = (L^\lnf_{\pi_{i-1}(v)}(u),s,\pi_{i-1}(v))
235	\end{equation}
236	where $i = \chi(s)$.
237	The function $L_\DLine$ is the concatenation of the following CL functions (again, see \Cref{lem:cl-concat} for definition of CL function concatenation): (i) the identity function on $V_{\coord}$ (which is a $1$-level CL function); (ii) for every $i \in \{1,2,\ldots,m\}$ the $1$-level CL function on $V_{\dir{}}$ that maps $v \mapsto \pi_{i-1}(v)$ (i.e.~it zeroes out the first $i-1$ coordinates of $v$), and (iii) for every pair $(s,v') \in V_\coord \oplus V_{\dir{}}$, the $1$-level CL function $L^\lnf_{v'}$ acting on $V_\xpt$. Thus $L_\DLine$ is a $3$-level CL function.
238	
239	
240	The following two lemmas establish that the CL functions
241	$L_\Point,L_\ALine,L_\DLine$ give rise to the axis-parallel line-versus-point and
242	diagonal line-versus-point distributions.
243	\begin{lemma}
244		\label{lem:alnf}
245		Consider the pair $(\line, u)$ sampled in the following way: first, sample the
246	  tuple $((u_0,s,0),(u,0,0))$ from the CL distribution $\mu_{L_\ALine,L_\Point}$,
247	  and let $\line = \line(u_0,e_i)$ where $i = \chi(s)$.
248	  Then $u$ is a uniformly random point in $\F_q^m$ and $\line$ is a line that
249	  goes through $u$ and is parallel to a uniformly random axis $i \in
250	  \{1,2,\ldots,m\}$.
251	\end{lemma}
252	\begin{proof}
253		Since $s$ is uniformly random in $\F_q$ and $m$ divides $q$ by assumption, we
254	  have that $i$ is uniformly random between $\{1,2,\ldots,m\}$ and therefore
255	  $(u_0,s)$ specifies a uniformly random axis-parallel line $\line(u_0,e_i)$.
256	  Since $u_0 = L^{\lnf}_{e_i}(u)$, we have that $u \in \line(u_0,e_i)$.
257	\end{proof}
258	
259	
260	
261	\begin{lemma}
262		\label{lem:dlnf}
263		Consider the pair $(\line,u)$ sampled in the following way: first, sample the
264	  tuple $((u_0,s,v),(u,0,0))$ from the CL distribution $\mu_{L_\DLine,L_\Point}$,
265	  and let $\line = \line(u_0,v)$ where $i = \chi(s)$.
266	  Then $u$ is a uniformly random point in $\F_q^m$ and $\line$ is a random
267	  diagonal line that goes through $u$ and shares the first $i-1$ coordinates
268	  with $u$, for uniformly random $i$.
269	\end{lemma}
270	\begin{proof}
271		The proof of this follows identically to \Cref{lem:alnf}.
272	\end{proof}
273	
274	For later convenience we make the following definition. 
275	
276	\begin{definition}[Line-point distributions]
277	        \label{def:line-point-dist}
278	 The \emph{axis line-point distribution} $D_{\ALine}$ is the
279	 distribution $\mu_{L_\ALine,L_\Point}$ over pairs $(\ell=(u_0,e_i),u)$
280	 (we omit the $0$ elements for simplicity). The \emph{diagonal
281	   line-point distribution} $D_{\DLine}$ is the distribution
282	 $\mu_{L_\DLine,L_\Point}$  over $(\ell=(u_0,s,v),u)$. The
283	 \emph{line-point distribution} $D_{\Line}$ is the equal mixture of the axis-parallel line-point distribution and the diagonal line-point distribution.
284	 In other words, a sample from $D_{\Line}$ is distributed as follows:
285	 with probability $\tfrac{1}{2}$, output a sample from $D_{\ALine}$,
286	 and with probability $\tfrac{1}{2}$, output a sample from $D_{\DLine}$.
287	\end{definition}
