368	    In all cases where no action is indicated, accept.
369	    For $w \in \AB$,
370	
371	    \begin{enumerate}
372	      \setlength\itemsep{1pt}
373	    \item (\textbf{Consistency test}) If $\tvar_\alice = \tvar_\bob$, accept iff
374	      $a_\alice = a_\bob$.
375	    \item (\textbf{Axis-parallel line-versus-point test}) If $\tvar_w = \ALine$
376	      and $\tvar_{\overline{w}} = \Point$, accept iff $f_j(t) =
377	      (a_{\overline{w}})_j$ for all $j \in \{1,2,\ldots,\ldc\}$ where $t \in
378	      \F_q$ is such that $x_{\overline{w}} = u_0 + te_i$ where $i = \chi(s)$.
379	      
380	    \item (\textbf{Diagonal line-versus-point test}) If $\tvar_w = \DLine$ and
381	      $\tvar_{\overline{w}} = \Point$, accept iff $f_j(t) =
382	      (a_{\overline{w}})_j$ for all $j \in \{1,2,\ldots,\ldc\}$ where $t \in
383	      \F_q$ is such that $x_{\overline{w}} = u_0 + tv'$, where $v' =
384	      \pi_{i-1}(v)$ with $i = \chi(s)$.
385	    \end{enumerate}
386	  \end{gamespec}
387	  \caption{The decision procedure $\decider^\ld$ for the simultaneous low-degree
388	    test, parameterized by $\ldparams = (q,m,d,\ldc)$.
389	    The function $\chi(s)$ is defined in \Cref{eq:chi-func}, and $\pi_{i-1}(v)$
390	    zeroes out the first $i-1$ coordinates of $v$.}
391	  \label{fig:ld-decider}
392	\end{figure}
393	
394	We define a special class of measurements that are relevant to the soundness
395	properties of the low-degree test.
396	
397	\begin{definition}[Low-degree polynomial measurements]
398	  \label{def:ld-meas}
399	  Define $\polymeas{m}{d}{q}$ to be the set of POVM measurements whose outcomes
400	  correspond to (individual) degree-$d$ polynomials of $m$ variables over
401	  $\F_q$.
402	  More generally, for an integer $\ldc$ and tuples $m=(m_1, m_2, \ldots,
403	  m_\ldc)$, $d=(d_1, d_2, \ldots, d_\ldc)$ and $q=(q_1, q_2, \ldots, q_\ldc)$,
404	  we let $\simulpolymeas{m}{d}{q}{\ldc}$ be the set of measurements $G =
405	  \{G_{g_1,\, g_2,\, \ldots\,,\, g_\ldc}\}$ such that for $i\in\{1, 2, \ldots,
406	  \ldc\}$, $g_i$ is a polynomial $g_i:\F_{q_i}^{m_i} \rightarrow
407	  \F_{q_i}$ with individual degree $d_i$ (see \Cref{sec:ld-encoding} for a definition of individual degree). 
408	\end{definition}
409	
410	Quantum soundness of a version of the classical low-degree test for polynomials of low \emph{total} degree was claimed
411	in~\cite{natarajan2018low}, building on an analysis of a three-prover version of the test in~\cite{vidick2016three}. Unfortunately there is a gap in the soundness analysis of this test. For our construction we use the low individual degree test, whose quantum soundness is shown in~\cite{ML20} and generalized in~\cite{ji2021quantum}. We state the result in the form that is most directly useful for us, and show how the stated result follows from~\cite{ji2021quantum}.
412	
413	\begin{theorem}[Quantum soundness of the simultaneous classical low-degree test]
414	  \label{lem:ld-soundness}
415	  There exists a function $\delta_{\ld}(\eps, q, m, d, \ldc) = a (dm \ldc)^a (\eps^b + q^{-b} + 2^{-bmd})$ for universal constants $a\geq 1$ and $0<b\leq 1$ 
416	such that the following
417	  holds.
418	  For all $\eps > 0$ and parameter tuple $\ldparams = (q, m, d, \ldc)$, for all
419	  projective strategies $(\psi,A,B)$ that succeed with probability at least
420	  $1-\eps$ in the game $\game^\ld_\ldparams$, there exists measurements
421	  \[G^w \in \simulpolymeas{m}{d}{q}{\ldc}\] on $\mH_w$, for
422	  $w\in\{\alice,\bob\}$, such that
423	  \begin{equation*}
424	    \begin{split}
425	      A^{\Point,\, u}_{a_1,\, a_2,\, \ldots\,,\, a_\ldc}
426	      & \abc[\delta_{\ld}]
427	      G^\bob_{[(g_1(u),g_2(u),\ldots,g_\ldc(u)) = (a_1,\, a_2,\, \ldots \,,\, a_\ldc)]}\;,\\
428	      G^\alice_{[(g_1(u),g_2(u),\ldots,g_\ldc(u)) = (a_1,\, a_2,\, \ldots \,,\, a_\ldc)]}
429	      & \abc[\delta_{\ld}]
430				 B^{\Point,\, u}_{a_1,\, a_2,\, \ldots\,,\, a_\ldc}\;,\\

409	\section{Conditionally linear functions and distributions}
410	% Paper subsection label sec:cl kept for cross-reference fidelity.
411	\label{sec:cl}
412	
413	Conditionally linear functions specify the question distributions of the games considered in the following chapters in a form that can be ``introspected''. Intuitively, a conditionally linear function takes as input an element $x \in V = \F^n$ and applies linear maps $L_j$ sequentially to $x^{V_j}$, where $V_1, V_2, \dots$ is a sequence of complementary register subspaces such that both the linear map $L_j$ and the subspace $V_j$, for $j \ge 2$, may depend on the values taken by the previous linear maps $L_1(x^{V_1})$, $L_2(x^{V_2})$, and so on.
414	
415	Throughout this section $V$ denotes the linear space $\F^n$ for some integer $n \ge 0$, and all the distinguished subspaces of $V$ are register subspaces (Definition~\ref{def:register-subspace}). If $V_1, V_2, \dots, V_\ell$ are fixed subspaces of $V$ and $k \in \{1, 2, \dots, \ell\}$, we use the subscript range notation
416	\[
417		V_{<k} = \bigoplus_{j\,:\,1 \le j < k} V_j\,, \qquad V_{>k} = \bigoplus_{j\,:\,\ell \ge j > k} V_j\,,
418	\]
419	and $V_{\le k}$, $V_{\ge k}$ are understood to be $V_{<k+1}$ and $V_{>k-1}$, respectively. For a register subspace $V'$ of $V$, the symbol $x^{V'}$ denotes the projection of $x$ onto $V'$ parallel to the complementary register subspace (Definition~\ref{def:complementary}). Moreover, if $F \colon V' \to V'$ is a function and $x \in V$, we write $x^F$ for $F(x^{V'})$; for example, in the following definition $x^{L_1}$ is shorthand for $L_1(x^{V_1})$.
420	
421	\begin{definition}[Conditionally linear functions]\label{def:cl-func}
422		\uses{def:register-subspace, def:complementary}
423		Let $V$ be $\F^n$ for some $n \ge 0$. For all integers $\ell \ge 0$ the collection of \emph{$\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is defined inductively as follows.
424		\begin{enumerate}
425			\item There is a single $0$-level conditionally linear function, which is the $0$ function on $V$.
426			\item Let $\ell \ge 1$ and suppose the collection of $(\ell-1)$-level conditionally linear functions has been defined. The collection of $\ell$-level conditionally linear functions on $V$ consists of all functions $L$ on $V$ that can be expressed in the following form: there exist complementary register subspaces $V_1$ and $V_{>1}$ of $V$, a linear function $L_1$ on $V_1$, and, for all $v \in L_1(V_1)$, an $(\ell-1)$-level conditionally linear function $L_{>1,\,v}$ on $V_{>1}$, such that for all $x \in V$,
427			\[
428				L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})\,.
429			\]
430		\end{enumerate}
431	\end{definition}
432	
433	We abbreviate ``conditionally linear'' as \emph{CL}. Operationally, an $\ell$-level CL function first applies $L_1$ to $x^{V_1}$; conditioned on the value $x^{L_1}$ it selects a register subspace $V_2$ and a linear map $L_2$ and applies $L_2$ to $x^{V_2}$; and so on, finally outputting $\sum_{k=1}^{\ell} x^{L_k}$. Every $1$-level CL function is linear, and conversely every linear map on $V$ is a $1$-level CL function. Moreover, for every $\ell \ge 1$ the collection of $\ell$-level CL functions contains the collection of $(\ell-1)$-level CL functions.
434	
435	\begin{definition}[Conditionally linear distributions]\label{def:cl-dist}
436		\uses{def:cl-func}
437		Let $L, R \colon V \to V$ be conditionally linear functions. The \emph{conditionally linear distribution $\mu_{L,R}$ corresponding to $(L,R)$} is the distribution over pairs $(L(x), R(x)) \in V \times V$ for $x$ drawn uniformly at random from $V$.
438	\end{definition}
439	
440	Note that both players' questions are generated from the \emph{same} uniformly random seed $x$; this shared-seed structure is what the introspection technique exploits. The following lemma elucidates the structural properties of $\ell$-level CL functions. Recall that $x^{L_{<k}}$ and $x^{L_k}$ denote $L_{<k}(x)$ and $L_{k,\,u}(x^{V_{k,\,u}})$ where $u = L_{<k}(x)$.
441	
442	\begin{lemma}[Structure of conditionally linear functions]\label{lem:cl-kth}
443		\uses{def:cl-func, def:register-subspace}
444		Let $\ell \ge 1$ and $V = \F^n$ for some integer $n \ge 0$. A function $L \colon V \to V$ is an $\ell$-level CL function if and only if the following collection of functions and subspaces exists:
445		\begin{enumerate}
446			\item[(i)] for each $k \in \{1, 2, \dots, \ell\}$, a function $L_{\le k} \colon V \to V$, called the \emph{$k$-th marginal of $L$};
447			\item[(ii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a register subspace $V_{k,\,u}$ of $V$, called the \emph{$k$-th factor space with prefix $u$};
448			\item[(iii)] for each $k \in \{1, 2, \dots, \ell\}$ and $u \in L_{<k}(V)$, a linear map $L_{k,\,u} \colon V_{k,\,u} \to V_{k,\,u}$, called the \emph{$k$-th linear map of $L$ with prefix $u$};
449		\end{enumerate}
450		such that the following conditions hold for all $k \in \{1, 2, \dots, \ell\}$:
451		\begin{enumerate}
452			\item $L_{\le k}$ is a $k$-level CL function on $V$;
453			\item $V = \bigoplus_{i=1}^{\ell} V_{i,\,x^{L_{<i}}}$ for all $x \in V$;
454			\item $L_{\le k}(x) = \sum_{i=1}^{k} x^{L_i}$ for all $x \in V$, where $L_i$ is shorthand notation for $L_{i,\,x^{L_{<i}}}$;
455			\item $L = L_{\le \ell}$.
456		\end{enumerate}
457		As in condition 3, we sometimes use $V_k$ and $L_k$ to denote $V_{k,\,u}$ and $L_{k,\,u}$ respectively, leaving the prefix $u$ implicit.
458	\end{lemma}
459	\begin{proof}
460		\uses{def:cl-func}
461		For the ``if'' direction, conditions 1 and 4 immediately exhibit $L$ as an $\ell$-level CL function. For the ``only if'' direction one constructs the marginals, factor spaces, and linear maps by induction on $\ell$. In the base case $\ell = 1$ take $L_{\le 1} = L$, $V_1 = V$, and $L_1 = L$. For the inductive step, write $L(x) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{V_{>1}})$ as in Definition~\ref{def:cl-func} and apply the inductive hypothesis to each $(\ell-1)$-level function $L_{>1,\,v}$, obtaining its marginals, factor spaces, and linear maps over $V_{>1}$. Define $L_{\le 1} = L_1$ with first factor space $V_1$, and for $k \ge 2$ define $L_{\le k}(x) = x^{L_1} + L'_{x^{L_1},\,<k}(x^{V_{>1}})$, with the $k$-th factor space and linear map of $L$ with prefix $u$ given by those of $L_{>1,\,v}$ at index $k-1$ with prefix $w$, where $v = u^{V_1}$ and $w = u^{V_{>1}}$. Conditions 1--4 are then verified directly from the inductive hypothesis: the direct-sum decomposition of $V_{>1}$ extends to $V$ by adjoining $V_1$, and the sum formula for $L_{\le k}$ follows by unfolding the inductive marginals.
462	\end{proof}
463	
464	The marginal functions, factor spaces, and linear maps of a given CL function $L$ need not be unique. For example, the identity function on $V = \F^n$ is a $1$-level CL function, but it can also be viewed as a $k$-level CL function for any $k \in \{2, \dots, n\}$ with an arbitrary partition of $V$ into factor spaces.
465	
466	\begin{lemma}[Concatenation of conditionally linear functions]\label{lem:cl-concat}
467		\uses{def:cl-func}
468		Let $\ell, k \ge 0$ be integers and let $U = \F^n$, $V = \F^m$ be linear spaces. Suppose $L$ is a $k$-level CL function on $U$ and, for each $u \in L(U)$, $R_u$ is an $\ell$-level CL function on $V$. Then the \emph{concatenation} $T$ of $L$ and $\{R_u\}_u$, defined by
469		\[
470			T(x) = L(x^U) + R_{L(x^U)}(x^V)\,,
471		\]
472		is a $(k+\ell)$-level conditionally linear function on $U \oplus V$.
473	\end{lemma}
474	\begin{proof}
475		\uses{def:cl-func}
476		By induction on $k$. The case $k = 0$ follows directly from Definition~\ref{def:cl-func}, since then $L = 0$ and $T$ acts by the single $\ell$-level function $R_0$ on the register subspace $V$. For the inductive step, write $L(x^U) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{U_{>1}})$ with complementary register subspaces $U_1$ and $U_{>1}$ of $U$. For each value $x^{L_1}$, the function $T_{>1,\,x^{L_1}}$ on $U_{>1} \oplus V$ sending $x^{U_{>1} \oplus V}$ to $L_{>1,\,x^{L_1}}(x^{U_{>1}}) + R_{x^{L_1} + x^{L_{>1}}}(x^V)$ is the concatenation of the $(k-1)$-level function $L_{>1,\,x^{L_1}}$ with a family drawn from $\{R_u\}$, hence is $(k+\ell-1)$-level by the induction hypothesis. The claim then follows from Definition~\ref{def:cl-func} applied with first subspace $U_1$ and first linear map $L_1$.
477	\end{proof}
478	
479	\begin{lemma}[Direct sums of conditionally linear functions]\label{lem:cl-func-prod}
480		\uses{def:cl-func, def:register-subspace}
481		Let $V^{(1)}, V^{(2)}, \dots, V^{(m)}$ be register subspaces of $V$ such that $V = \bigoplus_{j=1}^m V^{(j)}$. Suppose that, for each $j \in \{1, 2, \dots, m\}$, $L^{(j)}$ is an $\ell_j$-level conditionally linear function on $V^{(j)}$. Then the direct sum $L = \bigoplus_{j=1}^m L^{(j)}$, defined by
482		\[
483			L(x) = \sum_{j=1}^m L^{(j)}(x^{(j)})
484		\]
485		for all $x = \sum_{j=1}^m x^{(j)} \in \bigoplus_{j=1}^m V^{(j)}$, is an $\ell$-level CL function on $V$ for $\ell = \max_j \{\ell_j\}$.
486	\end{lemma}
487	\begin{proof}
488		\uses{def:cl-func}
489		Since an $\ell$-level CL function is also $k$-level conditionally linear for all $k \ge \ell$, it suffices to prove the claim when $\ell_j = \ell$ for all $j$. Proceed by induction on $\ell$. For $\ell = 1$ the functions $L^{(j)}$ are linear and the direct sum of linear maps is linear. For the inductive step, decompose each $L^{(j)}$ into its first-level linear part $L^{(j)}_1$ on $V^{(j)}_1$ and its family of $(\ell-1)$-level remainders $L^{(j)}_{>1,\,v_j}$ on $V^{(j)}_{>1}$. The direct sums of the first-level parts define a linear map on $V_1 = \bigoplus_j V^{(j)}_1$, and, for each prefix value $v = \sum_j v_j$, the direct sums of the remainders are $(\ell-1)$-level conditionally linear on $V_{>1} = \bigoplus_j V^{(j)}_{>1}$ by the induction hypothesis. This exhibits $L$ in the form required by Definition~\ref{def:cl-func}.
490	\end{proof}
491	
492	\begin{lemma}[Direct sums give product distributions]\label{lem:cl-dist-prod}
493		\uses{def:cl-dist, lem:cl-func-prod}
494		For each $i \in \{1, \dots, m\}$ let $L^{(i)}, R^{(i)} \colon V^{(i)} \to V^{(i)}$ be $\ell_i$-level conditionally linear functions, and let $L, R \colon V \to V$ be the direct sums $L = \bigoplus_i L^{(i)}$ and $R = \bigoplus_i R^{(i)}$, as defined in Lemma~\ref{lem:cl-func-prod}. Then the conditionally linear distribution $\mu_{L,R}$ is the product distribution $\prod_{i=1}^m \mu_{L^{(i)},\,R^{(i)}}$ over $V \times V$.
495	\end{lemma}
496	\begin{proof}
497		A uniformly random $x \in V$ has independent components $x^{(i)}$, each uniformly distributed in $V^{(i)}$. Hence the pair $(L(x), R(x)) = \bigl( (L^{(i)}(x^{(i)}))_{i=1}^m,\, (R^{(i)}(x^{(i)}))_{i=1}^m \bigr)$ is distributed exactly as the product of the distributions $\mu_{L^{(i)},\,R^{(i)}}$ for $i = 1, 2, \dots, m$.
498	\end{proof}
499	
500	\section{Typed conditionally linear distributions}
501	% Paper section label sec:types kept for cross-reference fidelity. Only the mathematical
502	% typed material (typed CL functions and distributions, graph distributions) is stated
503	% here; the typed sampler and verifier machinery of the source is outside the scope of
504	% the mathematical development.
505	\label{sec:types}
506	
507	The question distribution of the Pauli basis test is \emph{typed}: each question is a pair consisting of a type, drawn together with the other player's type from the edges of a fixed \emph{type graph}, and a question content, drawn from a CL distribution determined by the pair of types.
508	
509	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
510		\uses{def:cl-func}
511		Let $\mathcal T$ be a finite set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$.
512	\end{definition}
513	
514	% Nonemptiness of the edge set is stated explicitly here: with E empty, m = k = 0 and the
515	% normalization 1/(2m-k) below is undefined. The source
516	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
517	\begin{definition}[Graph distribution]\label{def:graph-distribution}
518		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
519		\[
520			\mu_G(u, v) =
521			\begin{cases}
522				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
523				0 & \text{otherwise}\,.
524			\end{cases}
525		\]
526		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
527	\end{definition}
528	
529	\begin{definition}[Typed conditionally linear distributions]\label{def:typed-cl-distributions}
530		\uses{def:typed-cl-functions, def:graph-distribution, def:cl-dist}
531		Let $\mathcal T$ be a type set and let $L = \{L_u\}_{u \in \mathcal T}$ and $R = \{R_v\}_{v \in \mathcal T}$ be $\mathcal T$-typed families of conditionally linear functions on $V$. Let $G = (\mathcal T, E)$ be a graph with vertex set $\mathcal T$. The \emph{$(\mathcal T, G)$-typed conditionally linear distribution $\mu^G_{L,\,R}$ corresponding to $(L, R)$} is the distribution over pairs $\bigl( (u, x), (v, y) \bigr)$, where the type pair $(u,v)$ is drawn from the graph distribution $\mu_G$ and the content pair $(x,y)$ is drawn from $\mu_{L_u,\,R_v}$.
532	\end{definition}
  1	\section{Types}
  2	\label{sec:types}
  3	
  4	We augment the definition of conditionally linear functions with a construct
  5	we call \emph{types}.
  6	A type~$\tvar$ is an element of a \emph{type set} $\type$, and a $\type$-typed
  7	family of conditionally linear functions is a collection
  8	$\{L_\tvar\}_{\tvar\in\type}$ containing a CL function $L_\tvar$ for each
  9	type~$\tvar\in\type$.
 10	The utility of this definition is that it allows us to define another object,
 11	namely conditionally linear distributions parameterized by an undirected graph
 12	$G = (\type, E)$ on the set of types known as a \emph{type graph}.
 13	Given two $\type$-typed families of conditionally linear functions
 14	$\{L_\lvar\}_{\lvar\in\type}, \{R_\rvar\}_{\rvar\in\type}$, the $(\type,
 15	G)$-typed conditionally linear distribution corresponding to them is the
 16	distribution which samples a pair of types $(\lvar, \rvar)$ uniformly at random
 17	from the edges of~$G$ (with each endpoint having equal probability as being
 18	chosen for $\lvar$ or $\rvar$, respectively) and then samples $(x, y)$ from
 19	$\mu_{L_\lvar,\, R_\rvar}$.
 20	The output is the pair $( (\lvar, x), (\rvar, y) )$.
 21	
 22	The normal form verifiers we present in the paper frequently use typed CL
 23	distributions to sample their questions, rather than untyped CL distributions.
 24	Types allow us to model the parts of their question distributions which are
 25	unstructured and unsuitable for being sampled from CL distributions.
 26	A common use of types is to allow the verifier to use previously defined games
 27	as subroutines.
 28	Here, the type helps indicate which subroutine the verifier selects, and an edge
 29	in the type graph between two different types allows us to introduce a test that
 30	cross-checks the results of one subroutine with the results of another.
 31	
 32	Finally, we show how to convert any typed CL distribution into an equivalent (in
 33	the precise sense defined below) untyped CL distribution with two additional
 34	levels, a technique we call \emph{detyping}.
 35	This entails showing how to ``simulate'' the \emph{graph distribution} of $G =
 36	(\type, E)$, i.e.\ the uniform distribution on its edges, using an untyped CL
 37	distribution.
 38	The simulation we give is based on rejection sampling and is only approximate:
 39	its quality degrades exponentially with the number of types in~$\type$.
 40	As a result, we will ensure throughout the paper that all type sets we consider
 41	are of a small, in fact generally constant, size.
 42	
 43	This section is organized as follows.
 44	In \cref{sec:typed-samplers} we define typed variants of CL distributions,
 45	samplers, deciders, and verifiers.
 46	In \cref{sec:graph-dist} we define a CL distribution which samples from the
 47	graph distribution of a given graph $G = (\type, E)$.
 48	In \cref{sec:detype} we define a canonical way to detype typed samplers,
 49	deciders, and verifiers using the graph sampler from \cref{sec:graph-dist}.
 50	We then prove the main result of the section, \cref{lem:detyping-verifiers},
 51	which relates the value of the detyped normal form verifier to the value of
 52	the original typed verifier.
 53	
 54	\subsection{Typed samplers, deciders, and verifiers}
 55	\label{sec:typed-samplers}
 56	
 57	\begin{definition}[Typed conditionally linear functions]
 58	  Let $\type$ be a finite set and $V$ be $\F^n$ for some integer $n \geq 0$.
 59	  A \emph{$\type$-typed family of $\ell$-level conditionally linear functions}
 60	  (implicitly, \emph{on $V$}) is a collection $\{L_\tvar\}_{\tvar \in \type}$
 61	  such that, for each $\tvar \in \type$, $L_\tvar$ is an $\ell$-level
 62	  conditionally linear function on~$V$.
 63	\end{definition}
 64	
 65	\begin{definition}[Graph distribution]
 66	  \label{def:graph-distribution}
 67	  Let $G = (U, E)$ be an undirected graph with vertex set $U$ and edge set~$E$.
 68	  Edges in~$E$ are written as multisets $\{u, v\}$ of two vertices; the case $u
 69	  = v$ represents a self-loop.
 70	  Suppose there are $m$ edges, $k$ of which are self-loops.
 71	  Then the \emph{graph distribution $\mu_G$ of~$G$} is the distribution over
 72	  $U\times U$ such that for every $(u, v)\in U\times U$,
 73	  \begin{equation*}
 74	    \mu_G(u, v) =
 75	    \begin{cases}
 76	      1/(2m-k) & \text{if $\{u, v\} \in E$},\\
 77	      0 & \text{otherwise}.
 78	    \end{cases}
 79	  \end{equation*}
 80	  This is identical to the uniform distribution over pairs $(u, v)\in U\times U$
 81	  such that $\{u, v\} \in E$.
 82	\end{definition}
 83	
 84	\begin{definition}[Typed conditionally linear distributions]
 85	  Let $\type$ be a type set and
 86	  $L=\{L_\lvar\}_{\lvar\in\type},R=\{R_\rvar\}_{\rvar\in\type}$ be $\type$-typed
 87	  families of conditionally linear functions on~$V$.
 88	  Let $G = (\type, E)$ be a graph with vertex set $\type$.
 89	  The \emph{$(\type, G)$-typed conditionally linear distribution $\mu_{L,\,
 90	      R}^G$ corresponding to~$(L, R)$} is the distribution over pairs $( (\lvar,
 91	  x), (\rvar, y) )$, where $(\lvar, \rvar)$ is drawn from $\mu_G$ and $(x,y)$ is
 92	  drawn from $\mu_{L_\lvar,\, R_\rvar}$.
 93	\end{definition}
 94	
 95	\begin{definition}[Typed conditionally linear samplers]
 96	  \label{def:typed-sampler}
 97		Let $q:\N \to \N$ be an admissible field size function and $s: \N \to \N$ be a
 98	  function.
 99	  Let $\type$ be a finite type set and let $G = (\type, E)$ be a graph with vertex set $\type$.
100	  A $7$-input Turing machine $\sampler$ is a \emph{$(\type, G)$-typed, $\ell$-level
101	    conditionally linear sampler with field size $q(n)$ and dimension $s(n)$} if
102	  for all $n \in \N$, letting $q = q(n)$ and $s = s(n)$, there exist
103	  $\type$-typed families of $\ell$-level conditionally linear functions
104	  $\{L^{\alice,\, n}_{\tvar}\}_{\tvar \in \type}$ and $\{L^{\bob,\,
105	    n}_{\tvar}\}_{\tvar \in \type}$ on $V = \F_q^s$ where $\tvar \in \type, w\in
106	  \AB$, the conditionally linear function $L^{w,\, n}_{\tvar}$ has marginal
107	  functions $\{L^{w,\, n}_{\tvar,\, \leq j}\}$ and factor spaces $\{V^{w,\,
108	    n}_{\tvar,\, j,\, u}\}$ satisfying the conditions of Lemma~\ref{lem:cl-kth},
109	  and for all $\tvar \in \type$, $w \in \ab$, $j \in \{1, \ldots, \ell\}$, and
110	  $z \in V$:
111	  \begin{itemize}
112	  \item On input $(n, \gamestyle{dimension})$, the sampler $\sampler$ returns
113	    the dimension $s(n)$.
114		
115		\item On input $(n, w, \gamestyle{marginal}, j, z, \tvar)$, the sampler
116	    $\sampler$ returns the binary representation of $L^{w,\, n}_{\tvar,\, \le
117	      j}(z)$.
118				
119				\item On input $(n, w, \gamestyle{linear}, j, u, y, \tvar)$, the sampler $\sampler$
120	    outputs the binary representation of $L^{w,\, n}_{\tvar,\, j,\, u}(y)$,
121	
122		\item On input $(n, w, \gamestyle{factor}, j, u, \tvar)$, the sampler
123	    $\sampler$ returns the factor space $V^{w,\, n}_{\tvar,\, j,\, u}$ of
124	    $L^{w,\, n}_{\tvar}$, represented as an indicator vector in $\{0,1\}^s$.
125	  \end{itemize}
126	  We call $\F_{q(n)}^{s(n)}$ the \emph{ambient space of $\sampler$}.
127	  We call $\{ L^{\alice,\, n}_{\tvar} \}, \{ L^{\bob,\, n}_{\tvar} \}$ the
128	  \emph{CL functions of $\sampler$ on index $n$}.
129	  The \emph{time complexity} of $\sampler$, denoted $\TIME_\sampler(n)$, is the
130	  number of steps before $\sampler$ halts for index $n$.
131	\end{definition}
132	
133	We assume that types $\tvar \in \type$ are represented using binary strings of
134	length at most $\lceil \log |\type| \rceil$; if a type $\tvar$ is given as input
135	to the sampler $\sampler$ and is not an element of $\type$, then the sampler
136	returns $0$.
137	Furthermore, as described in Remark~\ref{rmk:sampler-inputs} for un-typed
138	samplers, we write typed samplers with different numbers of arguments depending
139	on the input.
140	We note that Definition~\ref{def:typed-sampler} includes the graph $G$ as a parameter, even though it is not explicitly used anywhere;
141	this is so we can define the following concept, i.e.\ the \emph{distribution} of a typed sampler, which \emph{does} depend on $G$.
142	
143	\begin{definition}[Distribution of a typed sampler]
144	  \label{def:typed-sampler-sample}
145	  Let $\sampler$ be a $(\type, G)$-typed sampler.
146	  Let $L^w = \{ L^{w}_{\tvar} \}_\tvar$ for $w\in \{\alice, \bob\}$ be the CL
147	  functions of $\sampler$ on index~$n$.
148	  The \emph{distribution of sampler $\sampler$ on index $n$},
149	  denoted $\mu^G_{\sampler,\, n}$, is the $(\type, G)$-typed conditionally
150	  linear distribution corresponding to $(L^\alice, L^\bob)$.
151	\end{definition}
152	
153	\begin{definition}[Downsizing typed CL samplers]
154	  \label{def:downsize-typed-sampler}
155	Let $\sampler$ be a typed sampler.
156	  The typed downsized sampler $\downsize(\sampler)$ is defined as in
157	  Definition~\ref{def:downsize_sampler} with the only difference that the type
158	  $\tvar$ is included as part of the input to the sampler, as in
159	  Definition~\ref{def:typed-sampler}.
160	\end{definition}
