288		The question distribution of $\mathcal G^{\mathrm{pauli}}$ is the typed CL distribution on $\mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}} \times \mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}}$ obtained by sampling the type pair $(t_{\mathrm A}, t_{\mathrm B})$ from the graph distribution $\mu_{G^{\mathrm{pauli}}}$ of Definition~\ref{def:graph-distribution}, that is, uniformly at random among all ordered pairs of types whose underlying unordered pair $\{t_{\mathrm A}, t_{\mathrm B}\}$ is an edge of $G^{\mathrm{pauli}}$, self-loops included; sampling $z \in V^{\mathrm{pauli}}$ uniformly at random; and setting $x_w = L_{t_w}(z)$ for $w \in \{\mathrm A,\mathrm B\}$. Explicitly, if $z = (u_X,u_Z,s,v,r_X,r_Z)$, then a player whose type is $(\mathsf{Point},W)$ receives $u_W$; a player whose type is $(\mathsf{ALine},W)$ receives $(u_0, s)$ with $u_0 = L^{\mathrm{Ln}}_{e_i}(u_W)$ and $i = \chi(s)$; a player whose type is $(\mathsf{DLine},W)$ receives $(u_0, s, v')$ with $i = \chi(s)$, $v' = \pi_{i-1}(v)$, and $u_0 = L^{\mathrm{Ln}}_{v'}(u_W)$; a player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ receives $(u_X, u_Z, r_X, r_Z)$; and a player whose type is $(\mathsf{Pauli},W)$ receives $0$.
289	\end{definition}
290	
291	\begin{definition}[Win predicate of the Pauli basis test]\label{def:pauli-win-predicate}
292		\uses{def:pauli-question-distribution, def:ld-win-predicate, def:ms-game, def:indicator-vector, def:admissible}
293		Fix an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}) and let $M = 2^m$. Answers in the game $\mathcal G^{\mathrm{pauli}}_{\mathsf{qldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
294		% The paper's format table writes the line contents loosely as (u_W, s) and (u_W, s, v);
295		% by the sampling procedure the actual contents are the canonical pairs (u_0, s) and
296		% triples (u_0, s, v') with v' = pi_{i-1}(v). We state the canonical form.
297		\begin{itemize}
298			\item $(\mathsf{Point},W)$: content $y \in \F_q^m$; answer an element of $\F_q$.
299			\item $(\mathsf{ALine},W)$: content $(u_0, s) \in \F_q^m \times \F_q$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $d$.
300			\item $(\mathsf{DLine},W)$: content $(u_0, s, v') \in \F_q^m \times \F_q \times \F_q^m$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $md$.
301			\item $\mathsf{Pair}$: content $\omega = (u_X, u_Z, r_X, r_Z) \in (\F_q^m)^2 \times \F_q^2$; answer $(\beta_X, \beta_Z) \in \F_2^2$.
302			\item $(\mathsf{Pair},W)$: content $\omega$ as above; answer an element of $\F_2$.
303			\item $\mathsf{Constraint}_i$: content $\omega$ as above; answer $(\alpha_{v_1}, \alpha_{v_2}, \alpha_{v_3}) \in \F_2^3$, indexed by the variable indices $(v_1,v_2,v_3)$ of $\mathsf{Constraint}_i$.
304			\item $\mathsf{Variable}_j$: content $\omega$ as above; answer an element of $\F_2$.
305			\item $(\mathsf{Pauli},W)$: content $0$; answer an element of $\F_q^M$.
306		\end{itemize}
307		The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
308		\begin{equation}
309			\label{eq:gamma-value}
310			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
311		\end{equation}
312		where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
313		\begin{enumerate}
314			\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
315			\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$.
316			\begin{enumerate}
317				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
318				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
319			\end{enumerate}
320			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
321			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
322			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
323			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
324			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
325		\end{enumerate}
326		The game $\mathcal G^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
327	\end{definition}
328	
329	Note the one-sided gating on $\gamma$: the commutation check and the $\mathsf{Pair}$ consistency check accept automatically when $\gamma \neq 0$, while the Magic Square check and the $\mathsf{Variable}$ consistency check accept automatically when $\gamma = 0$.
330	
331	\begin{lemma}[Completeness of the Pauli basis test]\label{lem:pauli-completeness}
332		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:spcc, def:tensor-product-value}
333		For every admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}), the Pauli basis test $\mathcal G^{\mathrm{pauli}}_{\mathsf{qldparams}}$ has a value-$1$ SPCC strategy.
334	\end{lemma}
335	\begin{proof}
336		\uses{thm:ms-from-ac, def:bracket, def:consistent-measurement, def:EPR, def:indicator-vector, lem:pauli-observable-expansion, lem:twisted-commutation}
337		The strategy uses the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot M} \ot \ket{\mathrm{EPR}_2}$ with $M = 2^m$. On a question $((\mathsf{Point},W), y)$ a player measures the generalized Pauli basis POVM $\{\tau^W_h\}_{h \in \F_q^M}$ and reports $g_h(y)$; on $((\mathsf{ALine},W), \ell)$ or $((\mathsf{DLine},W), \ell)$ they report the restriction of $g_h$ to the line $\ell$, expressed as a univariate polynomial through the canonical parameterization of $\ell$; and on $(\mathsf{Pauli},W)$ they report $h$ itself --- in the bracket notation of Definition~\ref{def:bracket}, these measurements are $\tau^W_{[g_\cdot(y) = a]} \ot I$, $\tau^W_{[(g_\cdot)|_\ell = f]} \ot I$, and $\tau^W_a \ot I$. For a content $\omega = (u_X, u_Z, r_X, r_Z)$, consider the two binary measurements $A_b = \tau^X_{[\tr(g_\cdot(u_X)\, r_X) = b]} \ot I$ and $B_b = \tau^Z_{[\tr(g_\cdot(u_Z)\, r_Z) = b]} \ot I$. Since $g_h(u) = h \cdot \mathrm{ind}_m(u)$ (Chapter~\ref{chap:qpbt-algebra}), the relation between the Pauli projections and observables gives $\mathcal O_A = A_0 - A_1 = \tau^X(\mathrm{ind}_m(u_X)\, r_X) \ot I$ and $\mathcal O_B = \tau^Z(\mathrm{ind}_m(u_Z)\, r_Z) \ot I$, and the twisted commutation relation yields
338		\[
339			\mathcal O_A \mathcal O_B = (-1)^\gamma\, \mathcal O_B \mathcal O_A
340		\]
341		with $\gamma$ as in Equation~\eqref{eq:gamma-value}: the two measurements commute when $\gamma = 0$ and anticommute when $\gamma = 1$. If $\gamma = 0$, define $E^{\mathsf{Pair},\omega}_{\beta_X,\beta_Z} = A_{\beta_X} B_{\beta_Z}$ and $E^{(\mathsf{Pair},X),\omega}_a = A_a$, $E^{(\mathsf{Pair},Z),\omega}_a = B_a$, and let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be trivial (identity on the all-zeros outcome). If $\gamma = 1$, let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be those produced by Theorem~\ref{thm:ms-from-ac} from the anticommuting consistent pair $(A, B)$, acting on the auxiliary $\ket{\mathrm{EPR}_2}$ factor, and let the $\mathsf{Pair}$ measurements be trivial. The strategy is symmetric and projective by construction; every measurement is either a post-processed Pauli basis measurement, a measurement supplied by Theorem~\ref{thm:ms-from-ac}, or (in the $\gamma = 0$ case) a product of two commuting consistent measurements, so the strategy is consistent, and commutativity along every edge of $G^{\mathrm{pauli}}$ is checked case by case --- for instance, $(\mathsf{Point},X)$ and $\mathsf{Variable}_1$ commute because both are $X$-basis measurements. Consistency and projectivity give the consistency checks with certainty, and the low-degree checks pass because the answers agree with the strategy determined by the polynomial $g_h$ in the classical game. For the remaining checks: when $\gamma = 0$ the commutation check passes by construction, and when $\gamma = 1$ the Magic Square check passes by Theorem~\ref{thm:ms-from-ac}; the consistency checks 5 and 7 pass with certainty because $\tau^W_{[\tr(g_\cdot(y)\, r_W) = \cdot]} \ot I$ coincides with $E^{(\mathsf{Pair},W),\omega}$, respectively with the embedded $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ measurements of Theorem~\ref{thm:ms-from-ac} (item~3 there). Hence the strategy has value $1$.
342	\end{proof}
