369	\begin{corollary}[Qubit form of the soundness of the Pauli basis test]\label{cor:pauli-binary}
370		\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, def:povm-distance}
371		There exists a function
372		\[
373			\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
374		\]
375		% The paper's displayed function here writes the argument order (eps, q, m, d); the
376		% formula is the same, and its own item 1 reverts to (eps, m, d, q). See the remark below.
377		for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathcal G^{\mathrm{pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^2)^{\ot M \log q}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
378		\begin{enumerate}
379			\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
380			\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
381			\begin{align*}
382				\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\sigma^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
383				I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\sigma^W_u)_{\mathrm B''}\;,
384			\end{align*}
385			where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$. Here $\sigma^W_u$ denotes the tensor product of single-qubit Pauli measurements
386			\[
387				\bigotimes_{i=1}^{M} \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}\;,
388			\]
389			where $\kappa(u_i) = (u_{ij})_{1 \le j \le \log q}$ under the bijection $\kappa\colon \F_q \to \F_2^{\log q}$ of Chapter~\ref{chap:qpbt-algebra}.
390		\end{enumerate}
391	\end{corollary}
392	\begin{proof}
