155	\begin{definition}[Consistent strategies]\label{def:consistent-strategy}
156		\uses{def:consistent-measurement, def:projective-strategy-general}
157		Let $\mathcal S = (\ket{\psi}, A, B)$ be a projective strategy with state $\ket{\psi} \in \mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, defined on question alphabets $\mathcal X$ and $\mathcal Y$ and answer alphabets $\mathcal A$ and $\mathcal B$, respectively. We say that $\mathcal S$ is \emph{consistent} if for all $x \in \mathcal X$ the measurement $\{A^x_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$, and for all $y \in \mathcal Y$ the measurement $\{B^y_b\}_{b \in \mathcal B}$ is consistent on $\ket{\psi}$.
158	\end{definition}
